def regroup(apps, schema_editor):
    """"Indirect community" is now a group of its own: candidates whose recruitment records say so (in a community,
    category or tag column) move into it, unless HR set their group by hand."""
    from candidates.regions import classify

    Candidate = apps.get_model("candidates", "Candidate")
    fields = ["id", "source_records", "community_status", "state_of_origin", "country", "region"]
    for candidate in Candidate.objects.filter(region_fixed=False).only(*fields).iterator(chunk_size=2000):
        if "indirect" not in json.dumps(candidate.source_records or []).lower():
            continue
        group, note = classify(source_records=candidate.source_records, community_status=candidate.community_status,
                               state=candidate.state_of_origin, country=candidate.country)
        if group != candidate.region:
            Candidate.objects.filter(pk=candidate.pk).update(region=group, region_note=note)


